#pragma once

#include "CoreMinimal.h"

// The island's shape and landmarks, read once from Content/Terrain (generated by
// tools/generate_heightmap.py). Every machine reads the same files, so server and co-op clients
// build identical terrain and agree on where everything is.
struct UNREALSOULSLIKE_API FHebridesTerrain
{
	static const FHebridesTerrain& Get();

	static constexpr float CellSize = 300.f;
	static constexpr float HeightScale = 16000.f;

	int32 Resolution = 0;
	float SeaLevel = 0.2f;
	TArray<float> Heights;

	FVector2D LandingBeach = FVector2D(0.5f, 0.85f);
	FVector2D Broch = FVector2D::ZeroVector;
	FVector2D StandingStones = FVector2D::ZeroVector;
	FVector2D Keep = FVector2D(0.5f, 0.5f);
	FVector2D Boss = FVector2D(0.5f, 0.5f);
	TArray<FVector2D> PlayerStarts;
	TArray<FVector2D> Crofts;
	TArray<FVector2D> SkeletonSpawns;

	bool IsValid() const { return Resolution > 1 && Heights.Num() == Resolution * Resolution; }
	float WorldSize() const { return (Resolution - 1) * CellSize; }

	// World Z (sea level = 0) of grid vertex (X, Y).
	float GridZ(int32 X, int32 Y) const;

	// World Z at normalized (U, V), bilinear.
	float SampleZ(float U, float V) const;

	// World position on the terrain surface at normalized (U, V).
	FVector ToWorld(const FVector2D& UV) const;

	// Normalized (U, V) of a world XY position.
	FVector2D ToUV(const FVector& World) const;

private:
	void Load();
};

struct FSoulslikeAttachment
{
	FName Socket;
	FString Mesh;
};

struct FSoulslikeVisual
{
	FString Name;
	FString Mesh;
	TArray<FSoulslikeAttachment> Attachments;
	bool IsSet() const { return !Mesh.IsEmpty(); }
};

// Imported character art paths, from Content/Characters/CharacterAssets.json (written by
// tools/build_content.py). Every entry is optional: missing art falls back to placeholders.
struct UNREALSOULSLIKE_API FSoulslikeAssets
{
	static const FSoulslikeAssets& Get();

	FSoulslikeVisual Knight;
	FSoulslikeVisual Boss;
	TArray<FSoulslikeVisual> Skeletons;
	TMap<FName, FString> Anims;

private:
	void Load();
};
